class Solution {
public:
    int preimageSizeFZF(int k) {
        return helper(k) - helper(k - 1);
    }

    int helper(int k) {
        long l = 0, r = 5L * (k + 1);
        while (l < r) {
            long mid = l + (r - l) / 2;
            if (trailingZeroes(mid) <= k) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    int trailingZeroes(long n) {
        int count = 0;
        while (n) {
            count += n / 5;
            n /= 5;
        }
        return count;
    }
};
